/**
 * Loads the derived field catalog from the bundled JSON.
 *
 * The catalog is generated by scripts/derive-field-catalog.mjs and committed
 * to the repository. At runtime, it's imported as a static asset via the
 * @derived-catalog alias defined in vite.config.ts.
 */

import catalogData from "@derived-catalog";
import type { DerivedCatalog } from "../domain/case/types";

export const catalog: DerivedCatalog = catalogData as DerivedCatalog;
